SELECT id, email, country, segment, is_active, AVG(age) OVER (PARTITION BY segment, city ORDER BY signup_date, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS age_avg_5, ROW_NUMBER() OVER (PARTITION BY city, segment ORDER BY credit_limit, id) AS seq_no, AVG(age) OVER (PARTITION BY city ORDER BY signup_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS age_avg_3_prior FROM customers WHERE country IN ('DE', 'SG', 'TH')
